CREATE OR REPLACE FUNCTION private.require_vendor_session(p_session_token text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'extensions', 'pg_temp'
AS $function$
declare
  v_store_id uuid;
  v_token_hash bytea;
begin
  if coalesce(length(p_session_token), 0) < 32 then
    raise exception 'VENDOR_SESSION_INVALID'
      using errcode = '28000';
  end if;

  v_token_hash := digest(
    p_session_token,
    'sha256'
  );

  select s.store_id
  into v_store_id
  from public.vendor_sessions s
  join public.local_stores ls
    on ls.id = s.store_id
  where s.token_hash = v_token_hash
    and s.revoked_at is null
    and s.expires_at > now()
    and lower(
      trim(coalesce(ls.status, ''))
    ) = 'active'
  limit 1;

  if v_store_id is null then
    raise exception 'VENDOR_SESSION_INVALID'
      using errcode = '28000';
  end if;

  update public.vendor_sessions
  set last_seen_at = now()
  where token_hash = v_token_hash;

  return v_store_id;
end;
$function$

CREATE OR REPLACE FUNCTION private.v94_jsonb_object(p_value jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
declare
  v_result jsonb;
begin
  if p_value is null then
    return '{}'::jsonb;
  end if;

  if jsonb_typeof(p_value) = 'object' then
    return p_value;
  end if;

  if jsonb_typeof(p_value) = 'string' then
    begin
      v_result := (p_value #>> '{}')::jsonb;

      if jsonb_typeof(v_result) = 'object' then
        return v_result;
      end if;
    exception when others then
      return '{}'::jsonb;
    end;
  end if;

  return '{}'::jsonb;
end;
$function$
